import * as React from "react";

export type SearchIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SearchIcon({ size = 20, ...props }: SearchIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="11" cy="11" r="6" /><path d="M15.5 15.5 L20.5 20.5" />
    </svg>
  );
}
